// Shared small diffuse textures. Canvas details remain legible after console-resolution filtering.
import * as THREE from 'three';
import { drawTex, hash } from 'life/engine/look.js';
const SOURCES = {"wood": "data:image/jpeg;base64,", "varnish": "data:image/jpeg;base64,", "iron": "data:image/jpeg;base64,", "galvanized": "data:image/jpeg;base64,", "metal": "data:image/jpeg;base64,", "plastic": "data:image/jpeg;base64,", "fabric": "data:image/jpeg;base64,", "leather": "data:image/jpeg;base64,", "concrete": "data:image/jpeg;base64,", "terracotta": "data:image/jpeg;base64,", "rubber": "data:image/jpeg;base64,", "fur": "data:image/jpeg;base64,", "longfur": "data:image/jpeg;base64,", "gull": "data:image/jpeg;base64,", "pigeon": "data:image/jpeg;base64,", "duck": "data:image/jpeg;base64,", "sedan": "data:image/jpeg;base64,", "hatch": "data:image/jpeg;base64,", "suv": "data:image/jpeg;base64,", "pickup": "data:image/jpeg;base64,", "van": "data:image/jpeg;base64,", "bus": "data:image/jpeg;base64,", "taxi": "data:image/jpeg;base64,", "police": "data:image/jpeg;base64,", "glass": "data:image/jpeg;base64,", "grille": "data:image/jpeg;base64,", "keyboard": "data:image/jpeg;base64,", "screen": "data:image/jpeg;base64,", "cup": "data:image/jpeg;base64,", "food": "data:image/jpeg;base64,", "takeaway": "data:image/jpeg;base64,", "lantern": "data:image/jpeg;base64,", "dogface": "data:image/jpeg;base64,", "blackface": "data:image/jpeg;base64,", "whiteface": "data:image/jpeg;base64,", "paws": "data:image/jpeg;base64,", "gullhead": "data:image/jpeg;base64,", "pigeonhead": "data:image/jpeg;base64,", "duckhead": "data:image/jpeg;base64,", "book": "data:image/jpeg;base64,"};
const cache = new Map();
export function kitTexture(kind='metal') {
 if(cache.has(kind)) return cache.get(kind);
 if(kind==='spokes'){const t=drawTex(128,128,g=>{g.clearRect(0,0,128,128);g.strokeStyle='#b9b8ac';g.lineWidth=1;for(let i=0;i<32;i++){const a=i*Math.PI/16;g.beginPath();g.moveTo(64+Math.sin(a+1)*5,64+Math.cos(a+1)*5);g.lineTo(64+Math.sin(a)*60,64+Math.cos(a)*60);g.stroke();}g.beginPath();g.arc(64,64,60,0,Math.PI*2);g.lineWidth=3;g.stroke();});cache.set(kind,t);return t;}

 if(kind==='dogcoat'){const t=drawTex(128,128,g=>{g.fillStyle='#ddd0ae';g.fillRect(0,0,128,128);g.fillStyle='#403a33';g.beginPath();g.ellipse(53,10,44,32,-.1,0,Math.PI*2);g.fill();for(let i=0;i<1600;i++){const x=hash(i,7,2)*128,y=hash(i,9,3)*128;g.strokeStyle=`rgba(35,27,17,${.05+hash(i,2,4)*.15})`;g.beginPath();g.moveTo(x,y);g.lineTo(x+2,y+4);g.stroke();}});cache.set(kind,t);return t;}
 if(SOURCES[kind]) {const img=new Image(),t=new THREE.Texture(img);img.addEventListener('load',()=>{t.needsUpdate=true;});img.src=SOURCES[kind];t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;cache.set(kind,t);return t;}
 const tex=drawTex(128,128,g=>{
  g.fillStyle='#b9b7b0';g.fillRect(0,0,128,128);
  for(let y=0;y<128;y++) for(let x=0;x<128;x++) {
   let v=180+hash(x,y,8)*40;
   if(kind==='wood') v+=22*Math.sin(y*.65+Math.sin(x*.05)*2)-22;
   if(kind==='fur') v+=25*Math.sin(x*1.8+y*.2);
   if(kind==='fabric') v+=((x+y)%2)*20-20;
   if(kind==='foliage') v=90+hash(x>>2,y>>2,6)*120;
   if(kind==='metal' && hash(x>>1,y>>1,4)>.97) v-=75;
   g.fillStyle=`rgb(${v},${v},${v})`;g.fillRect(x,y,1,1);
  }
 });cache.set(kind,tex);return tex;
}
const materials=new Map();
export function kitMaterial(kind,color=0xffffff) {const key=kind+JSON.stringify(color);if(!materials.has(key))materials.set(key,new THREE.MeshLambertMaterial({map:kitTexture(kind),color:Array.isArray(color)?new THREE.Color(...color.map(v=>v/255)):color}));return materials.get(key);}
export function labelTexture(text,bg='#e5dfca',fg='#202829') {return drawTex(256,64,g=>{g.fillStyle=bg;g.fillRect(0,0,256,64);g.strokeStyle=fg;g.lineWidth=4;g.strokeRect(3,3,250,58);g.fillStyle=fg;g.font='bold 30px monospace';g.textAlign='center';g.fillText(text,128,43,240);});}
export function softTexture(){if(cache.has('soft'))return cache.get('soft');const t=drawTex(64,64,g=>{const r=g.createRadialGradient(32,32,0,32,32,32);r.addColorStop(0,'#fff');r.addColorStop(.35,'#777');r.addColorStop(1,'#000');g.fillStyle=r;g.fillRect(0,0,64,64);});cache.set('soft',t);return t;}
// Six atlas regions, two rows of four 64px tiles; UVs inset to prevent adjacent-tile bleed.
export function carAtlas(type='sedan'){if(cache.has('car-'+type))return cache.get('car-'+type);const t=drawTex(256,128,g=>{
 g.fillStyle='#ddd';g.fillRect(0,0,256,128);
 for(let y=0;y<128;y++)for(let x=0;x<256;x++){const v=215+hash(x,y,12)*25;g.fillStyle=`rgb(${v},${v},${v})`;g.fillRect(x,y,1,1);}
 // Body side: neutral paint, doors, handles, rocker grime, fuel flap.
 const grad=g.createLinearGradient(0,0,0,64);grad.addColorStop(0,'#ddd');grad.addColorStop(.12,'#fff');grad.addColorStop(.20,'#eee');grad.addColorStop(.3,'#aaa');grad.addColorStop(.7,'#bcbcbc');grad.addColorStop(1,'#555');g.fillStyle=grad;g.fillRect(0,0,64,64);
 g.strokeStyle='#666';g.lineWidth=.7;for(const x of [17,33,49]){g.beginPath();g.moveTo(x,3);g.lineTo(x,52);g.lineTo(x+3,56);g.stroke();}g.fillStyle='#555';for(const x of [21,37])g.fillRect(x,8,6,2);g.strokeRect(4,10,7,7);g.fillRect(0,48,64,2);
 for(let i=0;i<200;i++){g.fillStyle=`rgba(70,65,60,${hash(i,0,6)*.18})`;g.fillRect(hash(i,1,4)*64,48+hash(i,2,4)*16,3,1);}
 // Glass: rubber trim, reflected sky, dark seat silhouettes.
 g.fillStyle='#1e2830';g.fillRect(64,0,64,64);g.strokeStyle='#11191e';g.lineWidth=3;g.strokeRect(66,2,60,60);
 g.strokeStyle='#84969e';g.lineWidth=2;g.beginPath();g.moveTo(68,27);g.lineTo(123,10);g.stroke();
 g.strokeStyle='#47565e';g.lineWidth=5;g.beginPath();g.moveTo(68,32);g.lineTo(123,15);g.stroke();
 // Strong painted panel gradients, seams and edge reflections on the lid tile.
 const lid=g.createLinearGradient(128,0,192,64);lid.addColorStop(0,'#70787d');lid.addColorStop(.24,'#e8e8df');lid.addColorStop(.45,'#aaaeb0');lid.addColorStop(.7,'#f0f0e7');lid.addColorStop(1,'#626c73');g.fillStyle=lid;g.fillRect(128,0,64,64);
 for(const x of [140,173]){g.fillStyle='#454a4e';g.fillRect(x,2,1,60);g.fillStyle='#e9e9df';g.fillRect(x+1,2,1,60);}
 g.strokeStyle='#f1f0e7';g.lineWidth=1.3;g.strokeRect(130,3,60,58);
 // Rubber tread.
 for(let y=0;y<64;y+=4){g.fillStyle='#888';g.fillRect(192,y,64,1);}
 // Radial hub.
 g.fillStyle='#999';g.fillRect(0,64,64,64);g.fillStyle='#eee';g.beginPath();g.arc(32,96,28,0,Math.PI*2);g.fill();for(let i=0;i<8;i++){const a=i*Math.PI/4;g.fillStyle='#555';g.beginPath();g.ellipse(32+Math.cos(a)*19,96+Math.sin(a)*19,4,7,a,0,Math.PI*2);g.fill();}g.fillStyle='#999';g.beginPath();g.arc(32,96,8,0,7);g.fill();
 });
 const g=t.image.getContext('2d');
 if(type==='bus'){g.fillStyle='#575d64';g.fillRect(0,34,64,9);}
 if(type==='taxi'){g.strokeStyle='#9a3430';g.lineWidth=5;g.beginPath();g.moveTo(27,5);g.lineTo(36,43);g.stroke();}
 if(type==='police'){g.fillStyle='#28394b';g.fillRect(0,22,64,14);g.fillStyle='#ddd';g.font='7px sans-serif';g.fillText('POLICE',19,32);}
 // Grille, number plate and destination sign have dedicated, stable UV islands.
 g.fillStyle='#272c2c';g.fillRect(64,64,64,64);g.strokeStyle='#acafaa';g.lineWidth=2;g.strokeRect(67,67,58,58);
 for(let y=73;y<123;y+=7){g.fillStyle='#b9bdb9';g.fillRect(69,y,54,2);}g.fillRect(95,67,2,58);
 g.fillStyle='#d8d7c9';g.fillRect(128,64,64,64);g.fillStyle='#363a39';g.font='bold 14px monospace';g.fillText('JH 2847',130,102);
 g.fillStyle='#19231e';g.fillRect(192,64,64,64);g.fillStyle='#d6c992';g.font='bold 11px monospace';g.fillText('24',215,85);g.font='9px monospace';g.fillText('CENTRAL',196,108);
 if(type==='mustang'){
   // One long door per side; the rear quarter is uninterrupted over the wheel.
   const flank=g.createLinearGradient(0,0,0,64);
   for(const [stop,colour] of [[0,'#bcbec0'],[.16,'#eeefef'],[.25,'#969c9f'],[.72,'#c4c6c7'],[1,'#676a6b']])flank.addColorStop(stop,colour);
   g.fillStyle=flank;g.fillRect(0,0,64,64);
   g.strokeStyle='#626568';g.lineWidth=1;g.beginPath();g.moveTo(21,3);g.lineTo(22,46);g.quadraticCurveTo(23,51,26,51);g.lineTo(42,51);g.lineTo(44,5);g.stroke();
   for(let y=53;y<63;y+=3){g.fillStyle='#777a7c';g.fillRect(0,y,64,1);}
   // Black five-spoke wheels retain a narrow turned edge to catch the sun.
   g.fillStyle='#333637';g.fillRect(0,64,64,64);
   g.strokeStyle='#abaeb0';g.lineWidth=3;g.beginPath();g.arc(32,96,28,0,2*Math.PI);g.stroke();
   for(let i=0;i<5;i++){g.save();g.translate(32,96);g.rotate(i*Math.PI*2/5);
     g.fillStyle='#b9bcbe';g.beginPath();g.moveTo(-4,0);g.lineTo(-5,-22);g.lineTo(-2,-26);g.lineTo(4,-24);g.lineTo(4,0);g.fill();g.restore();}
   g.fillStyle='#85888a';g.beginPath();g.arc(32,96,7,0,2*Math.PI);g.fill();
   g.fillStyle='#252626';g.fillRect(128,64,64,64);g.fillStyle='#aaa99e';g.textAlign='center';g.font='bold 11px monospace';g.fillText('SAREINI',160,102);
 }
 t.wrapS=t.wrapT=THREE.ClampToEdgeWrapping;cache.set('car-'+type,t);return t;}


// Car-only lens atlas, shared by lit and unlit lamps.
export function carLensTexture(){if(cache.has('car-lens'))return cache.get('car-lens');const t=drawTex(128,64,g=>{
 for(let x=0;x<128;x++)for(let y=0;y<64;y++){
  const rear=x>=64,u=x%64,amber=u>47,base=amber?[222,115,15]:rear?[183,13,20]:[209,219,208];
  const k=(y%8<2?.53:1)*(u%9===0?.65:1)*(1-Math.abs(y-25)/115);
  g.fillStyle=`rgb(${base.map(v=>v*k).join(',')})`;g.fillRect(x,y,1,1);
 }g.fillStyle='#f1ddaa';g.fillRect(4,12,40,2);g.fillStyle='#ef5d4b';g.fillRect(68,12,40,2);
 });cache.set('car-lens',t);return t;}

// Collapse opaque kit pieces into one draw, retaining authored UVs and material tints.
// Images can finish loading after geometry: refresh the atlas when each source arrives.
export function mergeKitMeshes(root) {
 root.updateMatrixWorld(true);
 const meshes=[];root.traverse(m=>{if(m.isMesh&&m.material.isMeshLambertMaterial&&!m.material.transparent)meshes.push(m);});
 if(!meshes.length)return;
 const maps=[...new Set(meshes.map(m=>m.material.map))],n=Math.ceil(Math.sqrt(maps.length)),tile=256;
 const canvas=document.createElement('canvas');canvas.width=canvas.height=n*tile;const ctx=canvas.getContext('2d');
 const tex=new THREE.CanvasTexture(canvas);tex.magFilter=THREE.LinearFilter;
 maps.forEach((map,i)=>{const x=i%n*tile,y=Math.floor(i/n)*tile;const paint=()=>{ctx.fillStyle='#fff';ctx.fillRect(x,y,tile,tile);if(map?.image?.width){ctx.drawImage(map.image,x+2,y+2,252,252);ctx.drawImage(map.image,0,0,map.image.width,1,x+2,y,252,2);ctx.drawImage(map.image,0,map.image.height-1,map.image.width,1,x+2,y+254,252,2);}tex.needsUpdate=true;};paint();if(map?.image?.addEventListener&&!map.image.complete)map.image.addEventListener('load',paint);});
 const pos=[],normal=[],uv=[],colors=[],inv=root.matrixWorld.clone().invert();
 for(const m of meshes){const geo=m.geometry.index?m.geometry.toNonIndexed():m.geometry.clone(),matrix=inv.clone().multiply(m.matrixWorld);geo.applyMatrix4(matrix);const p=geo.attributes.position,no=geo.attributes.normal,u=geo.attributes.uv,c=geo.attributes.color,slot=maps.indexOf(m.material.map),tint=m.material.color;
 for(let i=0;i<p.count;i++){pos.push(p.getX(i),p.getY(i),p.getZ(i));normal.push(no?.getX(i)??0,no?.getY(i)??1,no?.getZ(i)??0);uv.push((slot%n+(2+(u?.getX(i)??0)*252)/256)/n,1-(Math.floor(slot/n)+(2+(1-(u?.getY(i)??0))*252)/256)/n);colors.push(tint.r*(c?.getX(i)??1),tint.g*(c?.getY(i)??1),tint.b*(c?.getZ(i)??1));}geo.dispose();m.removeFromParent();}
 const g=new THREE.BufferGeometry();
 g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
 g.setAttribute('normal',new THREE.Float32BufferAttribute(normal,3));
 g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
 g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
 const mesh=new THREE.Mesh(g,new THREE.MeshLambertMaterial({map:tex,vertexColors:true,side:THREE.DoubleSide}));
 root.add(mesh);return mesh;
}

// Flat contact core with a feathered perimeter; unlike lamp falloffs this carries alpha.
export function carShadowTexture(){if(cache.has('car-contact'))return cache.get('car-contact');const t=drawTex(128,128,g=>{const data=g.createImageData(128,128);for(let y=0;y<128;y++)for(let x=0;x<128;x++){const edge=Math.max(Math.abs(x-63.5)/63.5,Math.abs(y-63.5)/63.5);const a=Math.min(1,Math.max(0,(1-edge)/.19));const k=(y*128+x)*4;data.data[k]=data.data[k+1]=data.data[k+2]=255;data.data[k+3]=255*a*a*(3-2*a);}g.putImageData(data,0,0);});cache.set('car-contact',t);return t;}
export function shrubTexture(variant=0){const key='shrub-'+variant;if(cache.has(key))return cache.get(key);const t=drawTex(128,128,g=>{g.clearRect(0,0,128,128);for(let i=0;i<1500;i++){const x=hash(i,1,42)*120+4,y=hash(i,2,42)*120+4;const w=variant===1?y*.43:48+Math.sin(y*.13)*7;if(Math.abs(x-64)>w||variant!==1&&((x-64)**2/2800+(y-64)**2/2900)>1)continue;const v=55+hash(i,3,42)*100+(128-y)*.3;g.fillStyle=variant===2&&i%29===0?'#d2a3ac':`rgb(${v*.70},${v},${v*.55})`;g.beginPath();g.ellipse(x,y,2+hash(i,4,42)*3,1.8,hash(i,5,42)*6.28,0,6.28);g.fill();}});cache.set(key,t);return t;}
